/*  variabile
---------------------------------------------------------------------- */

:root {
  /* colors */
  --color-main: #00B2FF;
  --color-dark: #131D2F;
  --color-border: #E8E8E8;
  --color-light-bg: #F8F8F8;
  --color-grey: #999999;
  --color-dark-bg: #2E2E2E;
  --color-white: #FFFFFF;
  --color-black: #171717;

  /* border-radius */
  --border-radius: .25rem;

  /* shadows */
  --box-shadow: 0 3px 6px rgba(19, 29, 47, .27);
  --text-shadow: 0 3px 3px rgba(19, 29, 47, .27);
  --card-shadow: 0 .5rem 1rem rgba(19, 29, 47, .27);

  /* effects */
  --transition-effect: all .3s ease-out 0s;
}

/*  bootstrap overrides
---------------------------------------------------------------------- */

/* text */
p.lead {
  font-weight: 400;
}

/* buttons */
.btn {
  padding: 1.2rem 2.3rem 1.1rem;
  border-radius: 2.3rem;
  text-transform: uppercase;
  font-size: 13px;
  font-weight: 600;
  border-color: transparent;
  transition: var(--transition-effect);
  box-shadow: var(--box-shadow);
}
.btn:hover,
.btn:focus {
  border-color: transparent;
  box-shadow: none;
}
.btn.btn-primary {
  background-color: var(--color-main);
  color: var(--color-white);
}
.btn.btn-primary:hover,
.btn.btn-primary:focus {
  background-color: var(--color-dark);
  box-shadow: none;
}
.btn.btn-dark {
  background-color: var(--color-dark);
}
.btn.btn-dark:hover {
  background-color: var(--color-black);
} 

/* breadcrumbs */
ol.breadcrumb {
  margin-bottom: 0;
}
ol.breadcrumb li a,
.breadcrumb-item.active {
  color: var(--color-black);
  font-size: 1rem;
  font-weight: 600;
  text-transform: uppercase;
}
ol.breadcrumb li a:hover,
ol.breadcrumb li a:focus {
  color: var(--color-main);
}
.breadcrumb-item + .breadcrumb-item::before {
  color: var(--color-main);
}


/*  typography
---------------------------------------------------------------------- */

/* links */
a, a:hover, a:focus {
  color: var(--color-main);
  transition: var(--transition-effect);
  text-decoration: none;
  cursor: pointer;
}
a:active,
a:hover {
  outline: none;
}

/* text */
p {
  line-height: 1.7;
}
p:last-of-type {
  margin-bottom: 0;
}

